/**
 * The Help articles as plain text for the server (internal/helpdocs), so Ask
 * Stackurity and connected AI assistants can read the same steps people
 * read in Help (read_help). Generated by `npm run help-json`; a test fails
 * when internal/helpdocs/articles.json is out of date.
 */
import { ARTICLES } from "./help/articles";
import type { Article, Block } from "./help/types";

export interface ExportedArticle {
  id: string;
  title: string;
  section: string;
  summary: string;
  /** Menu path, e.g. "Administration › Integrations". */
  where: string;
  keywords: string;
  /** The body as Markdown: links to other articles become /help/ID. */
  text: string;
}

const links = (s: string) => s.replace(/\]\(help:([a-z0-9-]+)(#[a-z0-9-]+)?\)/g, "](/help/$1$2)");

function block(b: Block): string {
  if ("p" in b) return links(b.p);
  if ("h" in b) return `## ${b.h}`;
  if ("steps" in b) return b.steps.map((s, i) => `${i + 1}. ${links(s)}`).join("\n");
  if ("list" in b) return b.list.map((s) => `- ${links(s)}`).join("\n");
  if ("code" in b) return `${b.label ? `${b.label}:\n` : ""}\`\`\`${b.lang ?? ""}\n${b.code}\n\`\`\``;
  if ("note" in b) return `Note: ${links(b.note)}`;
  if ("warn" in b) return `Warning: ${links(b.warn)}`;
  const [head, ...rows] = b.table;
  return [head, head.map(() => "---"), ...rows].map((r) => `| ${r.map(links).join(" | ")} |`).join("\n");
}

export function exportArticle(a: Article): ExportedArticle {
  return {
    id: a.id,
    title: a.title,
    section: a.section,
    summary: a.summary,
    where: (a.where ?? []).join(" › "),
    keywords: a.keywords ?? "",
    text: a.body.map(block).join("\n\n"),
  };
}

/** The file's contents: stable, so an unchanged Help gives an unchanged file. */
export function helpJSON(): string {
  return JSON.stringify(ARTICLES.map(exportArticle), null, 1) + "\n";
}
